<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref} from 'vue';
import type {RequestFn} from './media';import {traffic,date,states} from './lib';
type Row=Record<string,any>;const props=defineProps<{request:RequestFn,initial?:string}>();
const rows=ref<Row[]>([]),selected=ref<Row|null>(null),usage=ref<Row|null>(null),devices=ref<Row[]>([]),clients=ref<Row[]>([]),links=ref<Record<string,Row>>({}),checks=ref<Record<string,Row>>({}),qr=ref(''),qrClient=ref(''),busy=ref(false),error=ref(''),notice=ref(''),filter=ref('');
const offset=ref(0),total=ref(0);let generation=0;
const formats=computed(()=>[{id:'auto',name:'自动识别客户端',note:'通用远程订阅；sing-box 扫码请选择专属格式'},...clients.value.filter(c=>c.id!=='auto')].filter(c=>!filter.value||String(c.name||c.id).toLowerCase().includes(filter.value.toLowerCase())));
const inactive=computed(()=>!!usage.value?.state&&!['active','unknown'].includes(usage.value.state));
const query=(id:string,c='auto')=>'?service='+encodeURIComponent(id)+'&client='+encodeURIComponent(c);
function clearQR(){if(qr.value)URL.revokeObjectURL(qr.value);qr.value='';qrClient.value=''}
function clearLinks(){links.value={};checks.value={};clearQR()}
async function act(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=false}}
async function list(){const d=await props.request('me/services?offset='+offset.value);rows.value=Array.isArray(d)?d:d.items;total.value=d.total??rows.value.length}
async function details(row:Row){const ticket=++generation,q=query(row.id);const s=await props.request('me/service'+q);if(ticket!==generation)return;usage.value=s.service;if(usage.value?.state){row.service_state=usage.value.state;const cached=rows.value.find(r=>r.id===row.id);if(cached)cached.service_state=usage.value.state}if(inactive.value){devices.value=[];clearLinks();return}const d=await props.request('me/devices'+q);if(ticket===generation)devices.value=Array.isArray(d)?d:d.items||[]}
async function open(row:Row){await act(async()=>{selected.value=row;usage.value=null;devices.value=[];clearLinks();await details(row)})}
async function getLink(c:string){if(!selected.value||inactive.value)return null;const id=selected.value.id,q=query(id,c);const checked=await props.request('me/subscription/check'+q);checks.value[c]=checked;if(!checked.ready)return null;const link=await props.request('me/subscription/share'+q);if(selected.value?.id!==id)return null;links.value[c]=link;return link}
async function reveal(c:string){await act(async()=>{await getLink(c)})}
async function copyLink(c:string){await act(async()=>{const d=await getLink(c);if(!d)return;try{await navigator.clipboard.writeText(d.url);notice.value='已复制此订单的 '+(clients.value.find(x=>x.id===c)?.name||'自动识别')+' 链接'}catch{notice.value='请选中此格式下方的链接手动复制'}})}
async function showQR(c:string){await act(async()=>{const d=await getLink(c);if(!d)return;const response=await fetch('/portal/v1/me/subscription/qr'+query(selected.value!.id,c),{credentials:'same-origin'});if(!response.ok){const data=await response.json().catch(()=>({}));throw new Error(data.error||'二维码暂不可用')}clearQR();qr.value=URL.createObjectURL(await response.blob());qrClient.value=c})}
let timer:ReturnType<typeof setInterval>;onMounted(()=>{void act(async()=>{await list();const d=await props.request('clients');clients.value=Array.isArray(d)?d:(d.clients||d.items||[]);let first=rows.value.find(r=>r.id===props.initial);if(!first&&props.initial){const d=await props.request('me/service?service='+encodeURIComponent(props.initial));if(!d.service)throw new Error('未找到该订单的订阅');first={...d.service,id:props.initial}}if(!props.initial)first=rows.value[0];if(first){selected.value=first;await details(first)}});timer=setInterval(()=>{if(document.visibilityState==='visible'&&!busy.value)void act(async()=>{await list();if(selected.value)await details(selected.value)})},30000)});onUnmounted(()=>{generation++;clearInterval(timer);clearQR()});
</script>
<template>
<div v-if="error" class="alert error" role="alert">{{error}}</div><div v-if="notice" class="alert" role="status">{{notice}}</div>
<section class="panel"><div class="section-head"><div><h3>我的独立订阅</h3><p class="muted">每个已核验订单对应一份订阅，分别计量与到期。选择订单后可查看各客户端的专属链接。</p></div></div>
<div class="service-grid"><article v-for="s in rows" :key="s.id" class="service-card" :class="{selected:selected?.id===s.id}"><div class="section-head"><h3>{{s.plan_name}}</h3><span class="badge" :class="s.service_state">{{states[s.service_state]||'待同步'}}</span></div><p>{{traffic(s.quota_bytes,s.quota_unit||'GB')}} / 月</p><small class="mono">订单 {{s.id}}</small><small>{{date(s.paid_at)}} 开通</small><span v-if="s.legacy_combined" class="badge">旧版合并权益</span><button class="service-open" :disabled="busy" @click="open(s)">{{selected?.id===s.id?'已选中 · 查看下方客户端链接':'查看此订单的客户端链接'}} →</button></article></div>
<div class="actions pagination" v-if="total>25"><button :disabled="busy||offset===0" @click="act(async()=>{offset=Math.max(0,offset-25);await list()})">上一页</button><span>{{offset+1}}–{{Math.min(offset+25,total)}} / {{total}}</span><button :disabled="busy||offset+25>=total" @click="act(async()=>{offset+=25;await list()})">下一页</button></div><p v-if="!rows.length" class="empty">尚未开通服务。已付款订单需等待身份和节点同步就绪。</p></section>
<section v-if="selected" class="panel"><div class="section-head"><div><h3>{{selected.plan_name}} · {{selected.id.slice(0,8)}}</h3><small class="mono">订单 {{selected.id}}</small></div><span class="badge">{{states[usage?.state]||'正在查询'}}</span></div>
<div v-if="usage&&!inactive" class="metrics"><article><span>剩余流量</span><strong>{{traffic(usage.remaining_bytes,usage.quota_unit||'GB')}}</strong></article><article><span>已用 / 本期配额</span><strong>{{traffic(usage.used_bytes,usage.quota_unit||'GB')}}</strong><small>{{traffic(usage.quota_bytes,usage.quota_unit||'GB')}}</small></article><article><span>到期时间</span><strong class="date">{{date(usage.expires_at)}}</strong></article></div>
<div v-if="inactive" class="alert error" role="status">此订单服务{{states[usage?.state]||'已失效'}}。订阅链接已停止展示，请联系管理员；订单与付款记录保留。</div>
<template v-else><div class="section-head client-heading"><div><h3>此订单的客户端导入链接</h3><p class="muted">不同格式使用同一订单权益。链接和二维码含凭据，请勿公开；不提供配置文件下载。</p></div><input v-model="filter" aria-label="查找客户端" placeholder="查找客户端…" type="search"></div>
<div class="client-grid"><article v-for="c in formats" :key="c.id" class="client-card" :data-client="c.id"><div><strong>{{c.name||c.label||c.id}}</strong><small>{{c.note||c.format||'远程订阅'}}</small></div><div class="actions"><button :disabled="busy||!usage" @click="reveal(c.id)">查看链接</button><button :disabled="busy||!usage" @click="copyLink(c.id)">复制</button><button :disabled="busy||!usage" @click="showQR(c.id)">二维码</button></div><p v-if="checks[c.id]&&!checks[c.id].ready" class="alert error">{{checks[c.id].reason||'此客户端暂没有可用节点'}}</p><label v-if="links[c.id]">{{c.name||c.id}} · 此订单链接<input :aria-label="(c.name||c.id)+' 订阅链接'" :value="links[c.id].url" readonly @focus="($event.target as HTMLInputElement).select()"></label><p v-if="checks[c.id]?.excluded_nodes" class="muted">已排除不兼容节点：{{checks[c.id].excluded_nodes}}</p><img v-if="qr&&qrClient===c.id" :src="qr" :alt="(c.name||c.id)+' 此订单订阅二维码'" width="180" height="180"></article></div><p v-if="!formats.length" class="empty">没有匹配的客户端</p></template></section>
<section v-if="selected&&!inactive" class="panel"><h3>此订阅的设备与客户端记录</h3><p class="muted">按所选订单的独立身份查询。未提供稳定设备标识时，无法保证物理设备去重。</p><div class="table-wrap"><table><thead><tr><th>客户端</th><th>名称</th><th>最近访问</th></tr></thead><tbody><tr v-for="(d,i) in devices" :key="d.id||i"><td>{{d.client_id||d.client||'未提供'}}</td><td>{{d.name||d.id}}</td><td>{{date(d.last_subscription_at||d.last_seen||d.updated_at)}}</td></tr></tbody></table></div><p v-if="!devices.length" class="empty">暂无客户端回传记录</p></section>
</template>
<style scoped>
.service-grid,.client-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,300px),1fr));gap:16px}.service-card{display:flex;flex-direction:column;padding:20px;border:1px solid #dce2ec;border-radius:12px;min-width:0}.service-card.selected{border-color:#377d74;background:#f5faf8}.service-card small{display:block;overflow-wrap:anywhere;margin:6px 0}.service-card h3{overflow-wrap:anywhere}.service-card .section-head{margin-bottom:8px;flex-wrap:wrap}.service-open{margin-top:auto;width:100%}.service-card small:last-of-type{margin-bottom:16px}.metrics{margin-bottom:18px}.pagination{margin-top:18px}.client-heading{flex-wrap:wrap}.client-heading input{max-width:240px}.client-card{min-width:0;padding:18px;border:1px solid #e1e7ef;border-radius:12px;display:flex;flex-direction:column;align-items:stretch;gap:14px}.client-card strong,.client-card small{display:block;overflow-wrap:anywhere}.client-card small{margin-top:6px;line-height:1.6}.client-card .actions{margin-top:auto}.client-card label,.client-card p{margin:0}.client-card input{font-size:12px}.client-card img{align-self:center;border:1px solid #e6ebf2;border-radius:10px;padding:6px}.badge.deleted,.badge.invalid,.badge.expired,.badge.disabled,.badge.exhausted{color:#ad604e;background:#ffede8}@media(max-width:600px){.client-heading input{max-width:none}.client-card{padding:16px}}
</style>
